import { tags } from "typia";

/**
 * Comprehensive security audit report for the shoppingMall platform that
 * aggregates critical security metrics from multiple system components to
 * provide administrators with a complete view of platform security posture and
 * compliance status.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallSecurityReport = {
  /**
   * Total number of system audit logs recorded in the last 30 days. These
   * logs capture administrative actions and configuration changes made by
   * admin users.
   *
   * Generated automatically by the system as side effects of admin
   * operations, not from direct API calls. Includes actions like user account
   * modifications, policy updates, and system configuration changes.
   *
   * Used for security posture assessment and compliance reporting. This
   * metric helps identify potential insider threats or unauthorized system
   * changes. Admins use this data to verify that all operational actions are
   * properly logged and to detect patterns of suspicious activity.
   */
  auditLogsCount: number & tags.Type<"int32">;

  /**
   * Total number of automated monitoring alerts triggered in the last 30
   * days. These alerts are generated by system health checks and anomaly
   * detection algorithms.
   *
   * Created automatically by monitoring services based on thresholds and
   * behavioral patterns. Includes events like unusual login patterns, payment
   * processing failures, and system resource exhaustion. These alerts serve
   * as early warning signals for potential security breaches or
   * infrastructure failures.
   *
   * Used for proactive system health monitoring. Admins analyze alert trends
   * to identify emerging threats before they cause service interruptions or
   * data compromise.
   */
  monitoringAlertsCount: number & tags.Type<"int32">;

  /**
   * Total number of active security policies configured on the platform. This
   * includes access control rules, authentication requirements, and data
   * protection policies.
   *
   * Managed through configuration systems and enforced automatically across
   * all services. Reflects the platform's security profile and compliance
   * posture. Policies govern how users authenticate, what privileges they
   * have, and how sensitive data is handled.
   *
   * Used to validate that security controls are properly implemented and
   * up-to-date. A low count may indicate insufficient protection, while a
   * high count may indicate overly complex and hard-to-manage policies.
   */
  securityPoliciesCount: number & tags.Type<"int32">;

  /**
   * Total number of payment gateway interaction logs recorded in the last 30
   * days. These logs capture all communication between the platform and
   * external payment processors.
   *
   * Generated automatically by payment processing services. Includes
   * successful transactions, failed authorizations, and timeout events. These
   * logs are essential for detecting payment fraud patterns, gateway
   * reliability issues, and transaction anomalies.
   *
   * Used for financial reconciliation and fraud detection. Admins use this
   * data to identify specific payment providers experiencing high failure
   * rates and to detect unusual transaction patterns indicative of payment
   * fraud.
   */
  paymentGatewayLogsCount: number & tags.Type<"int32">;

  /**
   * Total number of payment-related audit logs recorded in the last 30 days.
   * These logs capture financial transactions with detailed metadata for
   * reconciliation purposes.
   *
   * Created automatically by the payment subsystem during transaction
   * processing. Includes payment method changes, refund processing, and
   * currency conversion activities. These logs provide a complete financial
   * audit trail for every payment transaction.
   *
   * Essential for financial compliance and audit trails. Required for PCI-DSS
   * compliance and financial auditing. Used to verify that all financial
   * transactions are properly recorded, authorized, and traceable to their
   * source.
   */
  paymentAuditLogsCount: number & tags.Type<"int32">;

  /**
   * Total number of user flags raised in the last 30 days. These flags are
   * triggered by system detection of suspicious or policy-violating user
   * behavior.
   *
   * Automatically generated by user activity monitoring systems based on
   * predefined risk rules. Includes multiple failed login attempts, unusual
   * purchasing patterns, and account sharing detection. Flagging rules are
   * configured to identify potential account compromise, fraud, or policy
   * violations.
   *
   * Indicates potential security risks from user accounts and enables
   * targeted intervention. High flag counts trigger investigation workflows
   * and may lead to account suspension or additional authentication
   * challenges.
   */
  userFlagsCount: number & tags.Type<"int32">;

  /**
   * Total number of seller compliance records created in the last 30 days.
   * These records document seller adherence to platform policies and
   * regulatory requirements.
   *
   * Generated automatically during seller onboarding and periodic compliance
   * reviews. Includes document submission, verification status changes, and
   * policy violation records. Each record reflects a formal audit event that
   * verifies a seller maintains required certifications, licenses, and
   * business practices.
   *
   * Provides insight into marketplace trustworthiness and regulatory risk
   * exposure. Admins use this data to identify sellers requiring additional
   * oversight and to demonstrate regulatory compliance to governing
   * authorities.
   */
  sellerComplianceHistoryCount: number & tags.Type<"int32">;

  /**
   * Total number of product review moderation actions taken in the last 30
   * days. These logs capture reviews that have been flagged, reviewed, and
   * acted upon by moderation systems.
   *
   * Generated automatically by review moderation workflows triggered by user
   * reports or algorithmic detection. Includes actions like review removal,
   * reporting, and system notifications. The moderation system combines
   * automated filtering with human review for high-risk cases.
   *
   * Prevents malicious content and maintains community trust in product
   * ratings. High moderation activity indicates either high review volume or
   * potential manipulation of ratings systems, both of which require careful
   * monitoring.
   */
  reviewModerationLogsCount: number & tags.Type<"int32">;

  /**
   * Sum of all security, compliance, and integrity issues identified across
   * all systems in the last 30 days.
   *
   * Calculated as the total of auditLogsCount, monitoringAlertsCount,
   * userFlagsCount, sellerComplianceHistoryCount, and
   * reviewModerationLogsCount. This represents the aggregate count of all
   * security, compliance, and integrity events detected by the system.
   *
   * Provides an overall security health metric to assess platform integrity
   * and prioritize remediation efforts. A rising trend may indicate systemic
   * issues requiring architectural changes, while a consistent low count
   * indicates effective security posture.
   */
  totalIssueCount: number & tags.Type<"int32">;

  /**
   * Number of critical security issues requiring immediate attention
   * identified in the last 30 days.
   *
   * Calculated from high-severity monitoring alerts, verified user flags, and
   * confirmed payment fraud attempts. Critical issues are those that
   * represent active threats, ongoing breaches, or severe policy violations
   * that require immediate intervention.
   *
   * This metric directs prioritization of security response teams and
   * represents the most urgent threats to platform integrity. A high number
   * indicates active security incidents requiring immediate attention and
   * resource allocation.
   */
  criticalIssuesCount: number & tags.Type<"int32">;

  /**
   * Total count of policy violations detected across seller and customer
   * activities in the last 30 days.
   *
   * Aggregates violations from seller compliance history and user flag
   * systems. Includes prohibited product listings, fraudulent reviews,
   * payment fraud attempts, and other policy breaches. Each violation
   * represents a confirmed breach of platform terms of service or regulatory
   * requirements.
   *
   * Used to assess platform-wide compliance health and calculate risk scores.
   * Consistent violations across seller or user segments may indicate
   * systemic issues with policy enforcement or user education.
   */
  policyViolationCount: number & tags.Type<"int32">;

  /**
   * Number of automated and manual actions taken in response to detected
   * security issues in the last 30 days.
   *
   * Includes suspending user accounts, removing fraudulent reviews, blocking
   * payment methods, and applying penalties to non-compliant sellers. Actions
   * span both automated system responses and manual administrative
   * interventions.
   *
   * Measures system responsiveness and effectiveness of security controls. A
   * high number relative to issue count indicates rapid response
   * capabilities, while a low number may suggest insufficient resources or
   * delayed response procedures.
   */
  actionsTakenCount: number & tags.Type<"int32">;

  /**
   * Timestamp showing when this security report was last regenerated in UTC.
   * The report is refreshed daily at 02:00 UTC.
   *
   * This matters for understanding the recency of the provided data. All
   * metrics in the report are aggregated from events up to this timestamp.
   *
   * Webhooks and real-time monitoring systems use this timestamp to
   * synchronize their activity with the reported data. The lastUpdate
   * reflects the most recent complete data refresh, not live streaming.
   */
  lastUpdate: string & tags.Format<"date-time">;

  /**
   * Timestamp indicating when this specific security audit report was
   * generated. This differs from lastUpdate, which indicates the cutoff time
   * for data aggregation.
   *
   * This timestamp is critical for audit purposes to establish an exact
   * record of when this snapshot was produced, which can be useful in
   * forensic investigations. It provides a verifiable record of when this
   * specific report instance was created, independent of the data collection
   * period.
   */
  reportGenerationTime: string & tags.Format<"date-time">;

  /**
   * Identifies the system component that generated this security report. Must
   * be set to 'SecurityAuditService'.
   *
   * This is an automated system-generated report, not user-initiated. This
   * field serves as an authoritative source indicator.
   *
   * For traceability and accountability, this value is immutable and never
   * changes. It ensures that the report can be verified as originating from
   * the trusted SecurityAuditService component and not from any potential
   * tampering by administrators.
   */
  generatedBy: string;

  /**
   * List of all database tables and data sources used to generate this
   * security audit report.
   *
   * This is a complete list of system tables that contribute data to this
   * report. Ensures transparency about the data sources used for security
   * assessment and compliance verification.
   *
   * All these tables contain system-generated data created as side effects of
   * user operations, not direct input from API endpoints. The list must
   * exactly match the database schema names referenced in the operations
   * documentation to ensure traceability and validation.
   */
  dataSources: (
    | "shopping_mall_audit_logs"
    | "shopping_mall_monitoring_alerts"
    | "shopping_mall_security_policies"
    | "shopping_mall_payment_gateway_logs"
    | "shopping_mall_payment_audit_logs"
    | "shopping_mall_user_flags"
    | "shopping_mall_seller_compliance_history"
    | "shopping_mall_review_moderation_logs"
  )[];

  /**
   * Calculated security health score from 0 to 100 based on analysis of all
   * security indicators in this report.
   *
   * The score factors in:
   *
   * - Low issue counts (higher score)
   * - High action taken counts (higher score)
   * - Policy compliance (higher score)
   * - Critical issue counts (lower score)
   *
   * A score above 85 indicates strong security posture, 70-85 indicates good
   * with improvement opportunities, below 70 requires immediate attention.
   * The calculation applies weighted factors to each metric based on business
   * risk impact, with critical issues receiving the highest weight.
   */
  securityScore: number & tags.Minimum<0> & tags.Maximum<100>;

  /**
   * List of actionable security recommendations derived from analysis of the
   * report data.
   *
   * Each recommendation includes specific actions administrators can take to
   * address identified security concerns. Includes both technical
   * improvements and policy changes.
   *
   * Examples: 'Implement 2FA for all admin accounts', 'Review high-frequency
   * payment gateway failures', 'Increase review moderation staffing'. These
   * recommendations are prioritized based on impact and feasibility, with the
   * most critical items appearing first.
   */
  recommendations: string[];
};
